import{_ as e,o as t,c as s,a3 as i}from"./chunks/framework.BlfGB29P.js";const g=JSON.parse('{"title":"生态、包与版本边界","description":"按职责划分 LangChain.js 包分层，说明导入边界、@langchain/core 对齐与冲突排查，并给出本分组 API 地图。","frontmatter":{"title":"生态、包与版本边界","description":"按职责划分 LangChain.js 包分层，说明导入边界、@langchain/core 对齐与冲突排查，并给出本分组 API 地图。","outline":[2,3],"article":{"type":"concept","structure":"concept"}},"headers":[],"relativePath":"ts-ai/agent/langchain-core/ecosystem-packages-versioning.md","filePath":"ts-ai/agent/langchain-core/ecosystem-packages-versioning.md","lastUpdated":1786083160000}'),n={name:"ts-ai/agent/langchain-core/ecosystem-packages-versioning.md"};function d(h,a,l,o,r,c){return t(),s("div",null,[...a[0]||(a[0]=[i('<h1 id="生态、包与版本边界" tabindex="-1">生态、包与版本边界 <a class="header-anchor" href="#生态、包与版本边界" aria-label="Permalink to &quot;生态、包与版本边界&quot;">​</a></h1><blockquote><p>作者：cursor-grok-4.5</p></blockquote><p>LangChain.js 由多包组成：抽象在 <code>@langchain/core</code>，编排入口在 <code>langchain</code>，供应商在 <code>@langchain/openai</code> 等，状态图在 <code>@langchain/langgraph</code>。分不清边界会出现错误导入、多份 core 与类型冲突。</p><p>本篇只建包地图与版本规则。ChatModel、Message/Prompt、Runnable 见后续文章；<code>createAgent</code> 见<a href="/ts-ai/agent/runtime/create-agent">使用 createAgent 创建 Agent</a>。</p><h2 id="_1-为什么需要包边界" tabindex="-1">1. 为什么需要包边界 <a class="header-anchor" href="#_1-为什么需要包边界" aria-label="Permalink to &quot;1. 为什么需要包边界&quot;">​</a></h2><p>一次调用通常跨三层：</p><ol><li><strong>抽象层</strong>：Message、Runnable、ChatModel、Prompt。</li><li><strong>供应商层</strong>：接到 OpenAI、Anthropic 等 SDK。</li><li><strong>编排层</strong>：Agent Harness 或 LangGraph。</li></ol><p>包边界保证：应用依赖公开入口；多集成共享同一 <code>@langchain/core</code>；换供应商不等于重写编排。</p><h2 id="_2-包地图" tabindex="-1">2. 包地图 <a class="header-anchor" href="#_2-包地图" aria-label="Permalink to &quot;2. 包地图&quot;">​</a></h2><h3 id="_2-1-langchain-core" tabindex="-1">2.1 <code>@langchain/core</code> <a class="header-anchor" href="#_2-1-langchain-core" aria-label="Permalink to &quot;2.1 `@langchain/core`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>子路径</th><th>内容</th></tr></thead><tbody><tr><td><code>@langchain/core/messages</code></td><td><code>HumanMessage</code>、<code>AIMessage</code>、<code>SystemMessage</code>、<code>ToolMessage</code> 等</td></tr><tr><td><code>@langchain/core/prompts</code></td><td><code>PromptTemplate</code>、<code>ChatPromptTemplate</code>、<code>MessagesPlaceholder</code>、FewShot、Pipeline</td></tr><tr><td><code>@langchain/core/runnables</code></td><td><code>Runnable</code>、<code>RunnableSequence</code>、<code>RunnableLambda</code>、<code>RunnableBranch</code> 等</td></tr><tr><td><code>@langchain/core/output_parsers</code></td><td><code>StringOutputParser</code>、<code>JsonOutputParser</code> 等</td></tr><tr><td><code>@langchain/core/tools</code></td><td>工具相关抽象</td></tr></tbody></table><p><code>@langchain/core</code> 不含具体厂商 HTTP 客户端。</p><h3 id="_2-2-langchain" tabindex="-1">2.2 <code>langchain</code> <a class="header-anchor" href="#_2-2-langchain" aria-label="Permalink to &quot;2.2 `langchain`&quot;">​</a></h3><p>应用编排入口，例如：</p><div class="language-ts vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { createAgent, tool } </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">from</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;langchain&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h3 id="_2-3-供应商集成包" tabindex="-1">2.3 供应商集成包 <a class="header-anchor" href="#_2-3-供应商集成包" aria-label="Permalink to &quot;2.3 供应商集成包&quot;">​</a></h3><table tabindex="0"><thead><tr><th>包</th><th>典型导出</th></tr></thead><tbody><tr><td><code>@langchain/openai</code></td><td><code>ChatOpenAI</code>、<code>OpenAIEmbeddings</code></td></tr><tr><td><code>@langchain/anthropic</code></td><td><code>ChatAnthropic</code></td></tr><tr><td><code>@langchain/google-genai</code></td><td>Gemini 等</td></tr><tr><td><code>@langchain/ollama</code></td><td>Ollama</td></tr></tbody></table><p>本手册默认 <code>@langchain/openai</code> 的 <code>ChatOpenAI</code>。</p><h3 id="_2-4-langchain-langgraph-与周边" tabindex="-1">2.4 <code>@langchain/langgraph</code> 与周边 <a class="header-anchor" href="#_2-4-langchain-langgraph-与周边" aria-label="Permalink to &quot;2.4 `@langchain/langgraph` 与周边&quot;">​</a></h3><table tabindex="0"><thead><tr><th>包 / 能力</th><th>职责</th><th>手册位置</th></tr></thead><tbody><tr><td><code>@langchain/langgraph</code></td><td>状态图、Checkpoint、中断</td><td><a href="/ts-ai/workflow/">工作流与多 Agent</a></td></tr><tr><td>LangSmith</td><td>Trace、评测</td><td><a href="/ts-ai/quality/observability-reliability/opentelemetry-langsmith">OpenTelemetry 接线与 LangSmith 关联</a></td></tr><tr><td>MCP 适配</td><td>远程工具</td><td><a href="/ts-ai/agent/tools-mcp/">工具与 MCP</a></td></tr></tbody></table><h2 id="_3-推荐导入路径速查" tabindex="-1">3. 推荐导入路径速查 <a class="header-anchor" href="#_3-推荐导入路径速查" aria-label="Permalink to &quot;3. 推荐导入路径速查&quot;">​</a></h2><div class="language-ts vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { HumanMessage, AIMessage } </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">from</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;@langchain/core/messages&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { ChatPromptTemplate } </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">from</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;@langchain/core/prompts&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { RunnableSequence } </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">from</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;@langchain/core/runnables&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { ChatOpenAI } </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">from</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;@langchain/openai&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { createAgent, tool } </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">from</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;langchain&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p>避免：内部 <code>dist/</code> 路径、旧单体 <code>langchain/schema</code> 混用、把 core 打进业务 bundle 造成双实例。</p><h2 id="_4-langchain-core-单实例与版本对齐" tabindex="-1">4. <code>@langchain/core</code> 单实例与版本对齐 <a class="header-anchor" href="#_4-langchain-core-单实例与版本对齐" aria-label="Permalink to &quot;4. `@langchain/core` 单实例与版本对齐&quot;">​</a></h2><p>所有 LangChain 相关包必须共享<strong>同一主版本线</strong>的 <code>@langchain/core</code>。</p><p>症状：Message 类型不兼容、<code>pipe</code> 类型报错、<code>instanceof</code> 失败、Trace 断链。</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> langchain</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @langchain/core</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @langchain/openai</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> why</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @langchain/core</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>官方安装说明要求 Node.js 22+。用 override/resolutions 强制对齐后，回归最小 <code>invoke</code>。</p><h2 id="_5-安装、node-引擎与锁文件" tabindex="-1">5. 安装、Node 引擎与锁文件 <a class="header-anchor" href="#_5-安装、node-引擎与锁文件" aria-label="Permalink to &quot;5. 安装、Node 引擎与锁文件&quot;">​</a></h2><p>本分组最小依赖：</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @langchain/core</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @langchain/openai</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> OPENAI_API_KEY</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;...&quot;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>进入 Agent 再加：</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> langchain</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> zod</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>提交锁文件；CI 与本地 Node 大版本一致。版本表见<a href="/ts-ai/appendix/references/technology-stack-compatibility">技术栈与版本兼容表</a>。</p><h2 id="_6-冲突症状与排查" tabindex="-1">6. 冲突症状与排查 <a class="header-anchor" href="#_6-冲突症状与排查" aria-label="Permalink to &quot;6. 冲突症状与排查&quot;">​</a></h2><table tabindex="0"><thead><tr><th>症状</th><th>排查</th></tr></thead><tbody><tr><td>类型不过、运行勉强</td><td>多份 <code>@langchain/core</code></td></tr><tr><td>换供应商后 Message 全红</td><td>Message 是否仍从 <code>@langchain/core/messages</code> 导入</td></tr><tr><td>本地可跑、CI 失败</td><td>锁文件、Node、<code>engines</code>、override</td></tr><tr><td>Trace 不完整</td><td>是否绕开 Runnable、裸 <code>fetch</code> 调模型</td></tr></tbody></table><h2 id="_7-本分组-api-地图" tabindex="-1">7. 本分组 API 地图 <a class="header-anchor" href="#_7-本分组-api-地图" aria-label="Permalink to &quot;7. 本分组 API 地图&quot;">​</a></h2><table tabindex="0"><thead><tr><th>下一篇</th><th>收录</th></tr></thead><tbody><tr><td><a href="/ts-ai/agent/langchain-core/chat-model-chatopenai">ChatModel 与 ChatOpenAI</a></td><td>模型对象、返回值、<code>bindTools</code> / <code>withStructuredOutput</code> 点名</td></tr><tr><td><a href="/ts-ai/agent/langchain-core/messages-prompt-template">Message 与 Prompt 家族</a></td><td>消息类型、Prompt/FewShot/Pipeline</td></tr><tr><td><a href="/ts-ai/agent/langchain-core/runnable-invoke-batch-stream">Runnable：invoke、batch 与 stream</a></td><td>三种调用与 <code>RunnableConfig</code></td></tr><tr><td><a href="/ts-ai/agent/langchain-core/runnable-composition-events">Runnable 组合、容错与事件</a></td><td>Sequence/Map/Branch/Passthrough/Fallback 等器材表</td></tr></tbody></table>',38)])])}const k=e(n,[["render",d]]);export{g as __pageData,k as default};
